}

::deep .task-card h4 {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

::deep .task-assignee {
    margin: 0 0 0.25rem;
    font-size: 0.85rem;
    color: #666;
}

::deep .priority-badge {
    display: inline-block;
