toolArgs.file_text:
.board-columns {
    display: flex;
    gap: 1rem;
    margin-top: 1rem;
}

.loading {
    color: #666;
    font-style: italic;
}

.error {
    color: #d32f2f;
    font-weight: bold;
}

::deep .board-stats-bar {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    background: #f5f5f5;
    border-radius: 6px;
    margin-bottom: 1rem;
}

::deep .stat-overdue strong {
    color: #d32f2f;
}

::deep .board-search-bar {
    margin-bottom: 1rem;
}

::deep .board-search-bar input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

::deep .board-column {
    flex: 1;
    background: #f9f9f9;
    border-radius: 8px;
    padding: 1rem;
    min-width: 250px;
}

::deep .column-header h3 {
    margin: 0 0 0.75rem;
    font-size: 1.1rem;
}

::deep .task-card {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 0.75rem;
    margin-bottom: 0.5rem;
}

::deep .task-card h4 {
    margin: 0 0 0.25rem;
    font-size: 0.95rem;
}

::deep .task-assignee {
    margin: 0 0 0.25rem;
    font-size: 0.85rem;
    color: #666;
}

::deep .priority-badge {
    display: inline-block;
    padding: 0.15rem 0.5rem;
    border-radius: 3px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

::deep .priority-high {
    background: #ffcdd2;
    color: #c62828;
}

::deep .priority-medium {
    background: #fff9c4;
    color: #f57f17;
}

::deep .priority-low {
    background: #c8e6c9;
    color: #2e7d32;
}

::deep .task-due {
    font-size: 0.8rem;
    color: #888;
}

::deep .task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

::deep .btn-move {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 3px;
    background: #fff;
    cursor: pointer;
}

::deep .btn-move:hover {
    background: #e3f2fd;
}

::deep .btn-add-task {
    width: 100%;
    padding: 0.5rem;
    margin-top: 0.5rem;
    border: 1px dashed #bbb;
    border-radius: 4px;
    background: transparent;
    cursor: pointer;
    color: #666;
}

::deep .btn-add-task:hover {
    background: #f0f0f0;
}

::deep .add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 0.5rem;
    padding: 0.75rem;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
}

::deep .add-task-form input,
::deep .add-task-form select {
    padding: 0.4rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .form-actions {
    display: flex;
    gap: 0.5rem;
}

::deep .btn-save {
    padding: 0.4rem 0.75rem;
    background: #1976d2;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-cancel {
    padding: 0.4rem 0.75rem;
    background: #eee;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
}

